text:
{
  "title": "شروط وأحكام استخدام تطبيق \"نماء للخدمات الرقمية\"",
  "planted": [
    {
      "slot": "p1",
      "text": "للاستفادة من خدمات تطبيق \"نماء للخدمات الرقمية\" وإتمام إنشاء الحساب، يلتزم المستخدم بتقديم بيانات تفصيلية تشمل صورة الهوية الوطنية، الحالة الاجتماعية، عدد أفراد الأسرة، وتفاصيل الدخل الشهري، وذلك لضمان تقديم تجربة استخدام مخصصة."
    },
    {
      "slot": "p2",
      "text": "لا يحق للمستخدم بأي حال من الأحوال طلب الاطلاع على سجلاته الرقمية المحفوظة لدى الشركة، أو المطالبة بتصحيحها أو تعديلها، كما تظل كافة البيانات محفوظة نهائياً لدى الشركة دون إمكانية التقدم بطلب لحذفها."
    },
    {
      "slot": "p3",
      "text": "تمنح هذه الشروط الشركة صلاحية الاستفادة من كافة المعلومات والبيانات المدخلة عبر التطبيق لمختلف الأغراض التشغيلية الحالية والمستقبلية التي تقدرها الشركة، بما في ذلك تطوير خدمات جديدة أو مشاركتها مع أطراف أخرى لتحسين جودة الأداء."
    },
    {
      "slot": "p4",
      "text": "قبل استكمال عملية التسجيل، يمكن للمستخدمين مراجعة تفاصيل سياسة الخصوصية الشاملة التي توضح نوعية المعلومات التي يتم جمعها، وآليات المعالجة والتخزين، ومدد الاحتفاظ، وطرق التواصل مع فريق الدعم."
    },
    {
      "slot": "p5",
      "text": "تعتبر الموافقة على هذه الشروط إقراراً بالبدء في معالجة البيانات وفق الآليات المعتمدة لدى الشركة، مع خضوع استمرار تلك المعالجة لتقديرات الإدارة التشغيلية بما يخدم مصلحة العمل واستمرارية تقديم الخدمة."
    }
  ],
  "neutral": [
    "تخضع كافة المعاملات المالية وعمليات الدفع عبر التطبيق لرسوم الخدمة المقررة والمعلنة مسبقاً، والتي يتم خصمها تلقائياً عند إتمام كل عملية.",
    "يحق لأي من الطرفين إنهاء اتفاقية الاستخدام الحالية في أي وقت شريطة تقديم إشعار خطي مسبق للطرف الآخر قبل مدة لا تقل عن ثلاثين يوماً.",
    "لا تتحمل شركة \"نماء للخدمات الرقمية\" أي مسؤولية قانونية عن الأضرار غير المباشرة أو الخسائر المالية الناجمة عن انقطاع الخدمة أو سوء الاستخدام من قبل المستخدم.",
    "تخضع هذه الشروط والأحكام وتفسر وفقاً للأنظمة المعمول بها في المملكة العربية السعودية، وتختص المحاكم المختصة بالنظر في أي نزاع ينشأ عنها.",
    "يقصد بالتعاريف الواردة في هذه الاتفاقية المعاني المتعارف عليها تجارياً، وتعتبر العناوين الواردة فيها لغايات التسهيل فقط ولا تؤثر على تفسير بنودها.",
    "تظل كافة حقوق الملكية الفكرية والعلامات التجارية والتصميمات الخاصة بالتطبيق ملكية حصرية لشركة \"نماء للخدمات الرقمية\"، ولا يجوز استخدامها دون إذن خطي مسبق.",
    "تتم عملية تسليم المنتجات الرقمية أو الخدمات المتعاقد عليها فور اكتمال عملية الدفع الإلكتروني وتأكيد الطلب عبر الواجهة المخصصة في التطبيق.",
    "تعتبر كافة الإشعارات والمراسلات الموجهة للمستخدم صحيحة وم منتجة لآثارها القانونية إذا تم إرسالها عبر البريد الإلكتروني المسجل أو من خلال الإشعارات الداخلية للتطبيق."
  ]
}
